                  url: "https://www.nyrenews.org/news/2021/7/7/ny-renews-requests-urgent-meeting-with-assembly-to-fund-climate-justice-in-ny",
                  public_url:
                    "https://www.nyrenews.org/news/2021/7/7/ny-renews-requests-urgent-meeting-with-assembly-to-fund-climate-justice-in-ny",
