                  url: "https://www.smh.com.au/national/diagnosing-dementia-is-complicated-an-algorithm-could-change-that-20240704-p5jr0w.html",
                  public_url:
                    "https://www.smh.com.au/national/diagnosing-dementia-is-complicated-an-algorithm-could-change-that-20240704-p5jr0w.html",
